### Assumptions
1. `Request` and `Response` objects support standard streaming (`res.write`, `res.end`).
2. `db.order.iterate` accepts a `where` clause including `tenantId` and returns an async iterable.
3. We will use a helper function `csvEscape(value)` to handle commas, quotes, and newlines according to RFC 4180.

### Code Patch

```ts
// routes/export.ts
import { Request, Response } from 'express'; // Assuming express types
import { db } from '../db'; // Assuming db import
import { Writable } from 'stream';

/**
 * Robustly escapes a value for CSV format (RFC 4180).
 * Handles quotes, commas, and newlines by enclosing in double quotes
 * and doubling internal quotes (" -> "").
 */
function csvEscape(value: string | number | null | undefined): string {
  if (value === null || value === undefined) return '';
  const str = String(value);
  // Check if escaping is needed (contains comma, quote, or newline)
  if (str.includes(',') || str.includes('"') || str.includes('\n') || str.includes('\r')) {
    // Escape internal quotes by doubling them
    const escaped = str.replace(/"/g, '""');
    // Enclose the whole string in double quotes
    return `"${escaped}"`;
  }
  return str;
}

export async function exportOrders(req: Request, res: Response) {
  const { tenantId } = (req as any).user; // Assuming middleware sets req.user
  const status = req.query.status as string;

  if (!tenantId) {
    res.status(401).send("Unauthorized: Tenant ID missing.");
    return;
  }

  res.setHeader("Content-Type", "text/csv; charset=utf-8");
  res.setHeader("Content-Disposition", `attachment; filename="orders_${tenantId}.csv"`);

  try {
    // 1. Write header row immediately
    const header = "id,email,total\n";
    res.write(header);

    // 2. Iterate and stream rows
    const iterable = db.order.iterate({ where: { status, tenantId } });

    for await (const order of iterable) {
      // 3. Apply CSV escaping for cell values
      const row = [
        csvEscape(order.id),
        csvEscape(order.email),
        csvEscape(order.total),
      ].join(",");

      // 4. Stream chunk immediately
      res.write(row + "\n");
    }

    // 5. End the response stream
    res.end();

  } catch (error) {
    console.error("Error during CSV export:", error);
    // Ensure response is closed on error
    if (!res.headersSent) {
      res.status(500).send("Internal Server Error during export.");
    }
  }
}
